#!/usr/bin/env bash

# Compiles the Scheme files the Scheme converter generated by including the runtime and every one of them in one CHICKEN compilation unit, so
# the hand written runtime, the Scheme sources of the dependencies (META-INF/scheme/src of their jars),
# and this project are copied to one tree first. This project's sources are written to <output>/src.
# Arguments: source_dir output_dir object_dir dependency_dir runtime_dir compiler "flags" artifactId fail_on_error

set -uo pipefail

export PATH="/usr/local/bin:/usr/bin:/bin:$PATH"

source_dir="$(cygpath -u "$1")"
output_dir="$(cygpath -u "$2")"
object_dir="$(cygpath -u "$3")"
dependency_dir="$(cygpath -u "$4")"
runtime_dir="$(cygpath -u "$5")"
compiler="$(cygpath -u "$6")"
read -r -a compiler_flags <<< "$7"
artifact="$8"
fail_on_error="${9:-true}"

if [ ! -d "$source_dir" ]; then
    echo "No Scheme sources: $source_dir"
    exit 0
fi

rm -rf "$output_dir" "$object_dir"
tree="$object_dir/tree"
mkdir -p "$output_dir/src" "$tree"
cp -R "$source_dir/." "$output_dir/src/"
cp "$runtime_dir"/*.scm "$tree/"
if [ -d "$dependency_dir/src" ]; then
    cp -R "$dependency_dir/src/." "$tree/"
fi
cp -R "$source_dir/." "$tree/"

cd "$tree" || exit 1
check="jcheck_$artifact.scm"
{
    echo '(include "allbinary_java.scm")'
    # The dependencies then this project
    while IFS= read -r file; do
        echo "(include \"./$file\")"
    done < <(find . -type f -name '*.scm' ! -name 'allbinary_java.scm' ! -name 'jcheck_*' | sed 's|^\./||' | sort)
    echo "(display \"Scheme compiled: $artifact\")"
    echo '(newline)'
} > "$check"
echo "Scheme files: $(find "$source_dir" -type f -name '*.scm' | wc -l)"

output="$("$compiler" "${compiler_flags[@]}" -o "jcheck_$artifact" "$check" 2>&1 && "./jcheck_$artifact" 2>&1)"
status=$?
echo "$output"
if [ "$status" = "0" ] && ! echo "$output" | grep -q -i "warning"; then
    exit 0
fi
echo "Scheme build failed: $artifact" >&2
if [ "$fail_on_error" = "true" ]; then
    exit 1
fi
exit 0
